(function(root){
const copy=x=>JSON.parse(JSON.stringify(x)),methods=['first_frame','first_last_frames','reference_images'];
function plans(target){return target.generation?.video_methods;}
function method(target){const p=plans(target);return methods.includes(target.videoMethodOverride)?target.videoMethodOverride:methods.includes(p?.default_method)?p.default_method:'reference_images';}
function frame(target,position){return plans(target)?.first_last_frames?.[position==='first'?'first_frame':'last_frame'];}
function imageMethod(target,position){const f=frame(target,position),override=target.frameImages?.[position]?.methodOverride;return ['text_to_image','image_to_image'].includes(override)?override:f?.default_method||'text_to_image';}
function selected(target,position){const project=typeof data!=='undefined'?data:null;if(position==='last'&&project?.shotScript?.endpoint_generation_policy?.strategy==='next_shot_first'){const i=project.shots.findIndex(s=>(s.shot_id||s.id)===(target.shot_id||target.id));if(i>=0&&project.shots[i+1])return selected(project.shots[i+1],'first');return undefined;}const f=target.frameImages?.[position],versions=(f?.versions||[]).filter(j=>!j.deleted_at&&!target.deletedShotFrameIds?.includes(j.id));return versions.find(j=>j.id===f?.activeId)||versions.at(-1);}
function prompt(target){const p=plans(target),m=method(target);if(target.videoPromptOverrides?.[m]!==undefined)return target.videoPromptOverrides[m];if(m==='reference_images')return (p?.reference_images?.video_prompt??(target.clip_id?(target.custom_video_prompt||target.video_prompt):target.video_generation?.prompt))||'';return p?.[m]?.video_prompt||'';}
function validate(target){const p=plans(target);if(p===undefined)return;const fail=text=>{throw Error((target.shot_id||target.id)+'：'+text);};if(!p||typeof p!=='object'||Array.isArray(p))fail('video_methods 必须是对象');if(!methods.includes(p.default_method))fail('AI 推荐的视频方式无效');if(!p.recommendation_reason?.trim())fail('缺少推荐原因');for(const m of ['first_last_frames','reference_images',...(p.first_frame?['first_frame']:[])])if(typeof p[m]?.video_prompt!=='string'||!p[m].video_prompt.trim())fail(m+' 缺少视频提示词');if(p.default_method==='first_frame'&&!p.first_frame?.video_prompt?.trim())fail('仅首帧推荐缺少独立视频提示词');for(const position of ['first','last']){const f=frame(target,position);if(!f||!['text_to_image','image_to_image'].includes(f.default_method)||!f.recommendation_reason?.trim())fail('首尾帧推荐不完整');for(const m of ['text_to_image','image_to_image']){const d=f[m];if(typeof d?.prompt!=='string'||!d.prompt.trim()||typeof d.negative_prompt!=='string'||!d.negative_prompt.trim())fail('首尾帧需同时提供两种图片方案及正负提示词');if(m==='image_to_image'){if(!['picture_inputs','generated_first_frame'].includes(d.reference_source)||!Array.isArray(d.reference_tags)||d.reference_tags.some(t=>typeof t!=='string'))fail('图片参考来源无效');if(d.reference_source==='generated_first_frame'&&(position==='first'||d.reference_tags.length))fail('首帧不能引用自身，尾帧引用首帧时标签应为空');if(d.reference_source==='picture_inputs'){const tags=(target.picture_inputs||[]).map(r=>r.picture||r.tag);if(!d.reference_tags.length||new Set(d.reference_tags).size!==d.reference_tags.length||d.reference_tags.some(t=>!tags.includes(t)))fail('图生图引用了无效的参考标签');}}}}}
function sourceKey(target){return JSON.stringify({sub_shots:target.sub_shots,audio:target.audio,duration:target.duration,picture_inputs:target.picture_inputs});}
function reviewMethods(target){const p=plans(target);return p?methods.filter(m=>typeof p[m]?.video_prompt==='string'):['reference_images'];}
function modePrompt(target,m){return target.videoPromptOverrides?.[m]??plans(target)?.[m]?.video_prompt??(m==='reference_images'?(target.clip_id?(target.custom_video_prompt||target.video_prompt):target.video_generation?.prompt):'')??'';}
function reviewKey(target,m){return JSON.stringify([sourceKey(target),modePrompt(target,m)]);}
function invalidate(target){target.generationReviewRequired=true;target.videoPlanReviews={};for(const pos of ['first','last'])if(target.frameImages?.[pos])target.frameImages[pos].needsReview=true;}
function needsReview(target){return false;}
function accept(target,m){if(!reviewMethods(target).includes(m)||!modePrompt(target,m).trim())throw Error('请先填写并检查该方式的视频提示词');target.videoPlanReviews??={};target.videoPlanReviews[m]=reviewKey(target,m);target.generationReviewRequired=reviewMethods(target).some(k=>target.videoPlanReviews[k]!==reviewKey(target,k));}
function setPrompt(target,m,value){target.videoPromptOverrides??={};target.videoPromptOverrides[m]=value;if(plans(target)?.[m])plans(target)[m].video_prompt=value;if(m==='reference_images'){target.video_generation??={};target.generation??={};target.video_generation.prompt=target.generation.video_prompt=value;}if(target.videoPlanReviews){delete target.videoPlanReviews[m];target.generationReviewRequired=true;}}
const api={methods,plans,method,frame,imageMethod,selected,prompt,validate,sourceKey,reviewMethods,modePrompt,reviewKey,invalidate,needsReview,accept,setPrompt};
if(typeof module!=='undefined')module.exports=api;else{
 root.ShotMethods=api;const schema=root.ShotSchema,merge=schema.merge,rebuild=schema.rebuildMainPrompt;
 schema.merge=function(project,raw){for(const s of raw.shots||[])validate(s);const result=merge(project,raw);for(const s of result.project.shots||[]){const old=project.shots?.find(t=>(t.shot_id||t.id)===(s.shot_id||s.id));if(!old)continue;for(const k of ['frameImages','videoMethodOverride','frameResolution','pictureBindingOverrides','videoQuality','videoTailReferences','referenceListEdited','audioProduction','audioProductionKind','audioPanelOpen','videoPlanReviews','generationReviewRequired'])if(old[k]!==undefined)s[k]=copy(old[k]);if(sourceKey(old)!==sourceKey(s)||JSON.stringify(old.generation?.video_methods)!==JSON.stringify(s.generation?.video_methods)){s.videoPromptOverrides={};s.generationReviewRequired=false;s.videoPlanReviews={};}else if(old.videoPromptOverrides!==undefined)s.videoPromptOverrides=copy(old.videoPromptOverrides);}return result;};
 schema.rebuildMainPrompt=function(target,project){rebuild(target,project);invalidate(target);};
}
})(typeof window==='undefined'?globalThis:window);
